/* QEMU experiment: kexec's Multiboot v1 entry -> coreboot payload ABI.
 * The first module is an LBIO handoff generated by handoff.c. Copy it into
 * the reserved wrapper arena before CrabEFI can reclaim kexec's module pages.
 */
.section .text
.code32
.global _start
.balign 4
.long 0x1badb002, 3, -(0x1badb002 + 3)
_start:
    cli
    cld
    cmpl $0x2badb002, %eax
    jne halt
    testl $8, (%ebx)
    jz halt
    cmpl $1, 20(%ebx)
    jne halt
    movl 24(%ebx), %edx
    movl (%edx), %esi
    movl 4(%edx), %ecx
    subl %esi, %ecx
    jbe halt
    cmpl $0xc000, %ecx
    ja halt
    movl $0x08004000, %edi
    rep movsb
    movl $0x08004000, %eax
    movl $0x08004000, %esp
    pushl %eax
    pushl $0
    movl $PAYLOAD_ENTRY, %eax
    jmp *%eax
halt:
    hlt
    jmp halt
